/// <summary>
/// Servic class for Sales Invoice Dual Write Update abtch job.
/// </summary>
public class METSalesInvoiceDualWriteUpdateService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Processes sales orders that require Dual Write update.
/// </summary>
/// <param name="_contract">
/// The <see cref="METSalesInvoiceDualWriteUpdateContract"/> containing the item ID parameter for filtering sales lines.
/// </param>
public void process(METSalesInvoiceDualWriteUpdateContract _contract)
{
    Query               query;
    QueryRun            queryRun;
    METSalesLine        metSalesLine;
    CustParameters      custParameters = CustParameters::find();
    boolean             committPending = false;
    int                 counter = 1;    

    query = _contract.getQuery();

    if (query)
    {
        queryRun = new QueryRun(query);

        while (queryRun.next()) 
        {
            if (counter == 1)
            {
                ttsbegin;// Transaction start.
                committPending = true;
            }

            metSalesLine = queryRun.get(tableNum(METSalesTable));
            metSalesLine.ExcludeFromDualWrite = NoYes::No;
            metSalesLine.doUpdate();

            if (counter == custParameters.METSOInvoiceJobRecordCommitCount)
            {
                ttscommit;// Transaction end.
                committPending = false;
                counter = 0;
            }      

            counter++;
        }

        if (committPending == true)
        {
            ttscommit; // Transaction end.
        }      
    }
}
